const numObj = new Proxy({ val: 0 }, {
  set(target, prop, value) {
    if (typeof value !== "number") {
      throw new TypeError("Only numbers allowed")
    }
    target[prop] = value
    return true
  }
})
numObj.val = 42
try { numObj.val = "42" } catch(e) { return { val: numObj.val, error: e.message } }
return { val: numObj.val }
